# patch_lifeplus_site_v1.py  （lifeplus-site-v1 / site-contact-v1）
#  LIFE PLUS のホームページ（トップ・デイサービス・接骨院・ボディケア）を作る
#   ・docs/ の入口をホームページにし、予約ページは docs/yoyaku/ へ移す（中身は同じ）
#   ・デイサービスのページに、見学・相談のお問い合わせフォーム（関所の contact）
#   ・表：sql/lifeplus_contact_v1.sql（先に Supabase に流す）
# 何度流しても同じ結果。入れる前の形が違えば何もしないで止まる
import base64, zlib, hashlib, os, shutil, sys
FILES = [
  ("docs/index.html", 'ba61c46ee778e0d855c5ce473a0da92d', "64528ea18678c66f35991ad28d8711c8", ""),
  ("docs/dayservice/index.html", None, "be3184b6088374e72d1843fa76168400", ""),
  ("docs/sekkotsu/index.html", None, "70c3b169747b60d6f6b9b03461d46d40", ""),
  ("docs/bodycare/index.html", None, "bfeb9d2201c5f5760969674d988d21b1", ""),
  ("docs/site.css", None, "99ca3c3f99709ac7e749796c805ec4bb", ""),
  ("docs/site.js", None, "be4b1e23896ff1ab1e05d8e3177f178a", ""),
  ("docs/yoyaku/index.html", None, "cca697c69395ab5a5eb9dc452e8207ad", ""),
  ("docs/yoyaku/app.js", None, "0a285d9395c3b2b025c4f7b6aaf71242", ""),
  ("docs/yoyaku/style.css", None, "f62cc027be462f874374adfef60959db", ""),
  ("supabase/functions/booking/index.ts", '85235d38bf96bc9102d14463a46fda16', "13a4e0cbcec1bfa98c5a5d9ed2f466a1", ""),
  ("sql/lifeplus_contact_v1.sql", None, "5eadf80bde5dd9b1bb2cfefcb101c389", ""),
  ("tests/contact_test.ts", None, "5e55d956d187eb4fe8f3107b3ec2ef75", ""),
  ("tests/e2e_site_test.py", None, "644b45a66414a6fce1e5315443ad5eeb", ""),
  ("tests/e2e_test.py", '622f12e5caaf6f3a5f3e56e386825373', "49457443e5e80fa472fbb21231d72436", ""),
  ("README.md", '1aa9483d194067a9f0c22ec1a9eafcfc', "129a6ddbdb0d591be87c680635f5ccd3", ""),
]
REMOVE = {'docs/app.js': '0a285d9395c3b2b025c4f7b6aaf71242', 'docs/style.css': 'f62cc027be462f874374adfef60959db'}

def md5(p): return hashlib.md5(open(p, "rb").read()).hexdigest()
if not os.path.exists("docs/config.js") or not os.path.exists("supabase/functions/booking"):
    sys.exit("lifeplus-app のフォルダで流してください")
todo = []
for path, old, new, data in FILES:
    if os.path.exists(path):
        cur = md5(path)
        if cur == new:
            continue
        if old is None or cur != old:
            sys.exit("止めました：%s が思っていた形と違います（md5 %s）。何も変えていません" % (path, cur))
    elif old is not None:
        sys.exit("止めました：%s がありません。何も変えていません" % path)
    todo.append((path, new, data))
gone = []
for path, old in REMOVE.items():
    if os.path.exists(path):
        if md5(path) != old:
            sys.exit("止めました：%s が思っていた形と違います。何も変えていません" % path)
        gone.append(path)
if not todo and not gone:
    print("もう入っています（lifeplus-site-v1）"); sys.exit(0)
for path, new, data in todo:
    b = zlib.decompress(base64.b64decode(data))
    assert hashlib.md5(b).hexdigest() == new
    if os.path.exists(path):
        shutil.copy2(path, path + ".bak_site_v1")
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    open(path, "wb").write(b)
    assert md5(path) == new
for path in gone:   # 予約ページの部品は docs/yoyaku/ へ移したので、もとの場所からは消す
    shutil.copy2(path, path + ".bak_site_v1")
    os.remove(path)
print("入れました（lifeplus-site-v1）")
